var SECRET = '9f2c71d84b0e5a63c8d417f6ab92e05d73c1b8a4e6f90d21';
var item = $input.first().json;
var headers = item.headers || {};
var provided = String(headers['x-ais-secret'] || '');
var body = item.body || {};
var authorized = provided === SECRET && body && Object.prototype.toString.call(body.posts) === '[object Array]' && body.posts.length > 0;
return [{ json: { authorized: authorized, payload: body, secret: SECRET } }];

var data = $input.first().json;
var p = data.payload || {};
var ctx = p.context || {};
var posts = p.posts || [];
var keywords = ctx.keywords || [];
var phrases = ctx.phrases || [];
var out = [];
for (var i = 0; i < posts.length; i++) {
  var post = posts[i] || {};
  var content = String(post.content || '');
  if (content.length > 8000) { content = content.substring(0, 8000); }
  var prompt = '';
  prompt += 'WEBSITE: ' + String(p.site || '') + '\n';
  prompt += 'WEBSITE DESCRIPTION: ' + String(ctx.site_description || '') + '\n';
  prompt += 'TARGET AUDIENCE: ' + String(ctx.audience || '') + '\n';
  prompt += 'TARGET KEYWORDS: ' + keywords.join(', ') + '\n';
  prompt += 'TARGET PHRASES: ' + phrases.join(', ') + '\n\n';
  prompt += 'POST_ID: ' + String(post.id) + '\n';
  prompt += 'TYPE: ' + String(post.type || '') + '\n';
  prompt += 'URL: ' + String(post.url || '') + '\n';
  prompt += 'POST TITLE: ' + String(post.title || '') + '\n';
  prompt += 'CURRENT META TITLE: ' + String(post.current_meta_title || '(none)') + '\n';
  prompt += 'CURRENT META DESCRIPTION: ' + String(post.current_meta_desc || '(none)') + '\n';
  prompt += 'FLAGGED BECAUSE: ' + String(post.reason || '') + '\n\n';
  prompt += 'PAGE CONTENT (plain text, may be truncated):\n' + content;
  out.push({ json: {
    postId: post.id,
    postType: String(post.type || ''),
    url: String(post.url || ''),
    postTitle: String(post.title || ''),
    currentMetaTitle: String(post.current_meta_title || ''),
    currentMetaDesc: String(post.current_meta_desc || ''),
    reason: String(post.reason || ''),
    prompt: prompt,
    site: String(p.site || ''),
    callbackUrl: String(p.callback_url || ''),
    batchId: String(p.batch_id || ''),
    secret: data.secret
  }});
}
return out;

var inputs = $input.all();
var sources = $('Flatten Incoming Data').all();
var drafts = [];
var failures = [];
for (var i = 0; i < inputs.length; i++) {
  var j = inputs[i].json || {};
  var msg = j.message || {};
  var c = msg.content;
  var obj = null;
  if (c && typeof c === 'object') { obj = c; }
  else if (typeof c === 'string') { try { obj = JSON.parse(c); } catch (e) { obj = null; } }
  var src = sources[i] ? sources[i].json : {};
  if (obj) {
    var pid = (obj.post_id !== undefined && obj.post_id !== null) ? obj.post_id : src.postId;
    var match = src;
    for (var k = 0; k < sources.length; k++) {
      if (String(sources[k].json.postId) === String(pid)) { match = sources[k].json; break; }
    }
    drafts.push({
      post_id: pid,
      post_type: match.postType,
      url: match.url,
      proposed_title: String(obj.meta_title || '').trim(),
      proposed_description: String(obj.meta_description || '').trim(),
      rationale: String(obj.rationale || ''),
      current_title: match.currentMetaTitle,
      current_description: match.currentMetaDesc,
      reason: match.reason
    });
  } else {
    failures.push(src.postId);
  }
}
var first = sources[0] ? sources[0].json : {};
return [{ json: {
  batch_id: first.batchId,
  site: first.site,
  callback_url: first.callbackUrl,
  secret: first.secret,
  drafts: drafts,
  count: drafts.length,
  failed_ids: failures
} }];

var stats = $('Extract Drafts Data').first().json;
var resp = $input.first().json || {};
var delivered = !resp.error;
var navy = '#002657';
var orange = '#FA4616';
var rows = '';
var drafts = stats.drafts || [];
for (var i = 0; i < drafts.length; i++) {
  var d = drafts[i];
  rows += '<tr>';
  rows += '<td style="padding:8px;border-bottom:1px solid #e5e5e5;font-size:13px;">' + String(d.post_id) + '</td>';
  rows += '<td style="padding:8px;border-bottom:1px solid #e5e5e5;font-size:13px;">' + String(d.proposed_title) + '</td>';
  rows += '<td style="padding:8px;border-bottom:1px solid #e5e5e5;font-size:13px;">' + String(d.proposed_description) + '</td>';
  rows += '</tr>';
}
var statusLine = delivered
  ? '<p style="color:#1a7a1a;font-weight:bold;">Drafts delivered to ' + String(stats.site) + ' — review and approve in WP Admin → AIS SEO → Review Drafts.</p>'
  : '<p style="color:#b00020;font-weight:bold;">⚠️ Delivery to ' + String(stats.site) + ' FAILED after retries. Error: ' + String(resp.error && resp.error.message ? resp.error.message : 'unknown') + '</p>';
var failedNote = (stats.failed_ids && stats.failed_ids.length > 0)
  ? '<p style="color:#b00020;">Could not parse AI output for post IDs: ' + stats.failed_ids.join(', ') + '</p>'
  : '';
var html = '';
html += '<div style="font-family:Barlow,Arial,sans-serif;max-width:720px;margin:0 auto;">';
html += '<div style="background:' + navy + ';padding:16px 20px;"><span style="color:#ffffff;font-size:18px;font-weight:bold;">AI Solutions</span> <span style="color:' + orange + ';font-size:18px;font-weight:bold;">— SEO Meta Drafts</span></div>';
html += '<div style="padding:20px;">';
html += '<p style="font-size:14px;">Batch <strong>' + String(stats.batch_id) + '</strong> for <strong>' + String(stats.site) + '</strong>: ' + String(stats.count) + ' draft(s) generated.</p>';
html += statusLine + failedNote;
html += '<table style="border-collapse:collapse;width:100%;margin-top:12px;"><tr style="background:#f4f4f4;"><th style="text-align:left;padding:8px;font-size:13px;">Post</th><th style="text-align:left;padding:8px;font-size:13px;">Proposed Title</th><th style="text-align:left;padding:8px;font-size:13px;">Proposed Description</th></tr>' + rows + '</table>';
html += '<p style="margin-top:24px;font-size:12px;color:#888;">Automated Intelligent Solutions, Inc. · automatedintelligentsolutions.com · 404-293-0331 · user@example.com</p>';
html += '</div></div>';
return [{ json: { subject: 'SEO Meta Drafts Ready — ' + String(stats.site) + ' (' + String(stats.count) + ')' + (delivered ? '' : ' — DELIVERY FAILED'), html: html } }];
